            if (string.IsNullOrEmpty(dominio) || dominio.Contains('@', StringComparison.Ordinal) || dominio.Any(char.IsWhiteSpace))
            {
                throw new DomainException($"Domínio de e-mail inválido na lista: '{bruto}'.");
