95	  quem?: "aluno" | "instituicao";
96	}
97	
98	// Reivindicação de prêmio de participação (produto.md 4.6 e 4.7): o prêmio, o evento, da
99	// lista ou digitado com nome e período, e a matéria quando o prêmio pede (apresentação em
100	// sala). Sem prancheta: segue a identidade visual, em linhas como as do modal de medalha.
101	// Escolhido o prêmio, a lista recolhe para ele, com "Trocar prêmio": o catálogo tem 17 itens
102	// e empurraria o evento para longe da foto.
103	export function EscolhaDaReivindicacao({
