112	  const daInstituicao = quem === "instituicao";
113	  const item = itens.find((candidato) => candidato.codigo === valor.item);
114	  const exigeMateria = item?.exigeMateria ?? false;
115	  const eventos = useEventosDoItem(item && !exigeMateria ? item.codigo : null);
116	  const materias = useMaterias(exigeMateria);
117	  const digitado = exigeMateria || valor.eventoId === OUTRO_EVENTO;
118	  const mudar = (parcial: Partial<Escolha>) =>
119	    onChange({ ...valor, ...parcial });
120	
121	  return (
122	    <View style={styles.coluna}>
123	      <View style={styles.secao}>
124	        <Titulo texto="Prêmio" />
125	        <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
126	          {daInstituicao
127	            ? "O prêmio que a instituição concede, já aprovado."
128	            : "O prêmio que a foto comprova."}
129	        </Text>
130	        {(item ? [item] : itens).map((opcao) => (
131	          <Linha
132	            key={opcao.codigo}
133	            marcada={valor.item === opcao.codigo}
134	            rotulo={`${opcao.nome}, ${rotulosDeTier[opcao.tier as Tier]}, ${opcao.pontos} pontos`}
135	            onPress={() =>
136	              onChange({
137	                ...ESCOLHA_VAZIA,
138	                item: opcao.codigo,
139	                nome: valor.nome,
140	                inicio: valor.inicio,
141	                fim: valor.fim,
142	              })
143	            }
144	          >
145	            <Medalhao tier={opcao.tier as Tier} glifo="taca" size={40} />
146	            <View style={styles.texto}>
