151	              <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
152	                {opcao.criterio}
153	              </Text>
154	            </View>
155	          </Linha>
156	        ))}
157	        {item && (
158	          <View style={styles.trocar}>
159	            <TextLink
160	              label="Trocar prêmio"
161	              onPress={() =>
162	                onChange({
163	                  ...valor,
164	                  item: null,
