185	              {eventos.isPending && <ActivityIndicator color={colors.ink2} />}
186	              {eventos.isError && (
187	                <ErrorState
188	                  message={falhaParaTela(eventos.error).mensagem}
189	                  onRetry={() => void eventos.refetch()}
190	                />
191	              )}
192	              {(eventos.data ?? []).map((evento) => (
