204	                      {periodo(evento.inicio, evento.fim)}
205	                    </Text>
206	                  </View>
207	                </Linha>
208	              ))}
209	              <Linha
210	                marcada={valor.eventoId === OUTRO_EVENTO}
211	                rotulo="Outro evento"
212	                onPress={() => mudar({ eventoId: OUTRO_EVENTO })}
213	              >
214	                <View style={styles.texto}>
215	                  <Text style={[textStyles.secao, { color: colors.ink }]}>
216	                    Outro evento
217	                  </Text>
218	                  <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
