222	              </Linha>
223	            </>
224	          )}
225	
226	          {digitado && (
227	            <View style={styles.campos}>
228	              <TextField
229	                label={
230	                  exigeMateria
231	                    ? daInstituicao
232	                      ? "O que o aluno apresentou"
233	                      : "O que você apresentou"
234	                    : "Nome do evento"
235	                }
236	                value={valor.nome}
237	                onChangeText={(nome) => mudar({ nome })}
238	                placeholder={
239	                  exigeMateria
240	                    ? "Seminário de normalização"
241	                    : "Palestra sobre LGPD"
242	                }
243	              />
244	              <TextField
245	                label="Data de início"
246	                value={valor.inicio}
247	                onChangeText={(inicio) => mudar({ inicio })}
248	                placeholder="dd/mm/aaaa"
249	                keyboardType="numbers-and-punctuation"
250	                error={
251	                  valor.inicio.trim() !== "" && !lerData(valor.inicio)
252	                    ? "Use o formato dd/mm/aaaa."
253	                    : undefined
254	                }
