257	                label="Data de fim, se durou mais de um dia"
258	                value={valor.fim}
259	                onChangeText={(fim) => mudar({ fim })}
260	                placeholder="dd/mm/aaaa"
261	                keyboardType="numbers-and-punctuation"
262	                error={
263	                  valor.fim.trim() !== "" && !lerData(valor.fim)
264	                    ? "Use o formato dd/mm/aaaa."
265	                    : undefined
266	                }
267	              />
268	            </View>
269	          )}
270	        </View>
271	      )}
272	
273	      {exigeMateria && (
274	        <View style={styles.secao}>
275	          <Titulo texto="Matéria" />
276	          {materias.isPending && <ActivityIndicator color={colors.ink2} />}
277	          {materias.isError && (
278	            <ErrorState
279	              message={falhaParaTela(materias.error).mensagem}
280	              onRetry={() => void materias.refetch()}
281	            />
282	          )}
283	          {materias.isSuccess && materias.data.length === 0 && (
284	            <Text style={[textStyles.legenda, { color: colors.ink3 }]}>
285	              {daInstituicao
286	                ? "O aluno não tem matéria neste semestre."
287	                : "Você não tem matéria neste semestre."}
288	            </Text>
289	          )}
290	          {(materias.data ?? []).map((materia) => (
291	            <Linha
292	              key={materia.id}
293	              marcada={valor.materiaId === materia.id}
294	              rotulo={materia.nome}
295	              onPress={() => mudar({ materiaId: materia.id })}
296	            >
297	              <Text
298	                style={[textStyles.secao, styles.texto, { color: colors.ink }]}
299	              >
300	                {materia.nome}
301	              </Text>
302	            </Linha>
303	          ))}
304	        </View>
305	      )}
306	    </View>
307	  );
308	}
309	
310	function Titulo({ texto }: { texto: string }) {
311	  const { colors } = useTheme();
312	  return (
313	    <Text role="heading" style={[textStyles.secao, { color: colors.ink }]}>
314	      {texto}
315	    </Text>
316	  );
317	}
318	
319	function Pontos({ tier, pontos }: { tier: Tier; pontos: number }) {
320	  const { colors, name } = useTheme();
