322	    <Text style={textStyles.legenda}>
323	      <Text style={{ color: tiers[tier].texto[name] }}>
324	        {rotulosDeTier[tier]}
325	      </Text>
326	      <Text style={{ color: colors.ink2 }}>{` · +${pontos}`}</Text>
327	    </Text>
328	  );
329	}
330	
331	// Uma opção de escolha única, como as do modal de medalha: borda em ink quando marcada.
332	function Linha({
333	  marcada,
334	  rotulo,
335	  onPress,
336	  children,
337	}: {
338	  marcada: boolean;
