// TEMPORÁRIO, fora do commit: captura do achado do passo 6 do ensaio para a revisão do autor.
import { expect, test } from "@playwright/test";

import { novaConta } from "./apoio/contas";

test("captura: trocar o prêmio escolhido", { tag: "@celular" }, async ({ page, request }, info) => {
  const aluno = await novaConta(request, "Captura");
  await page.goto("/login");
  await page.getByLabel("RA ou e-mail").fill(aluno.ra);
  await page.getByLabel("Senha", { exact: true }).fill(aluno.senha);
  await page.getByRole("button", { name: "Entrar", exact: true }).click();
  await page.getByRole("button", { name: "Novo post" }).first().click();
  await page.getByRole("radio", { name: "Reivindicar prêmio" }).click();

  const premio = page.getByRole("radio", { name: /^Semana acadêmica,/ });
  await premio.click();
  await expect(page.getByRole("heading", { name: "Evento" })).toBeVisible();
  await premio.scrollIntoViewIfNeeded();
  const pasta = process.env.MAXX_CAPTURA_DIR ?? ".";
  await page.screenshot({ path: `${pasta}/passo6-${info.project.name}-1-escolhido.png` });

  await premio.click();
  await expect(page.getByRole("radio", { name: /^Apresentação de trabalho em sala/ })).toBeVisible();
  await expect(page.getByRole("heading", { name: "Evento" })).toHaveCount(0);
  await premio.scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${pasta}/passo6-${info.project.name}-2-lista-de-volta.png` });
});

